#!/usr/bin/env bash
# PreToolUse hook on Write/Edit: block edits to files marked as autogenerated.
set -u
file=$(jq -r '.tool_input.file_path // empty')
[ -f "$file" ] || exit 0
if head -n 10 "$file" | grep -Eiq 'auto-?generated|do not edit|generated by|this file is generated'; then
  echo "Blocked: $file is marked as autogenerated (see its header). Never edit it by hand. Change the source it is generated from and regenerate it." >&2
  exit 2
fi
exit 0
